def dehydrate_timedelta(value):
    """Dehydrate a datetime.timedelta into total seconds as an integer.

    :param value: datetime.timedelta instance to dehydrate.
    :type value: datetime.timedelta
    :return: int, total number of seconds represented by the timedelta, or None if value is None or not a timedelta.
    """
    if value is None:
        return None
    if not isinstance(value, timedelta):
        return None
    return int(value.total_seconds())

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    # Return an ISO 8601 compliant string representation of the time
    return value.isoformat()

