def unit_of_work(metadata=None, timeout=None):
    """
    Decorator to wrap a transaction function with optional metadata and timeout.
    The wrapped function will be executed inside a transaction that starts with
    the supplied metadata and timeout values. If the provided session already
    represents an open transaction it will be reused.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            # The first positional argument is expected to be a session or a transaction
            if not args:
                raise TypeError("unit_of_work expects at least one argument (session or transaction)")
            session = args[0]

            # If the session is already a transaction (no begin_transaction method), just call the function
            if not hasattr(session, "begin_transaction"):
                return func(*args, **kwargs)

            # Start a new transaction with the desired configuration
            try:
                tx = session.begin_transaction(timeout=timeout, metadata=metadata)
            except TypeError:
                # Fallback for drivers that don't accept keyword arguments
                tx = session.begin_transaction()

            try:
                result = func(tx, *args[1:], **kwargs)
                tx.commit()
                return result
            except Exception:
                tx.rollback()
                raise
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        return wrapper
    return decorator

def index(self, key):
        """
        Return the index of the given item.

        :param key: a key
        :return: index
        :rtype: int
        """
        if isinstance(key, int):
            return key
        try:
            return self._index.index(key)
        except ValueError:
            raise KeyError('Key not found: %s' % key)

def values(self, *keys):
    """Return the values of the record, optionally filtering to
    include only certain values by index or key.
    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # If no keys given, return all values
    if not keys:
        if hasattr(self, "_items"):
            # Record stores values in a list attribute named _items
            return list(self._items)
        # Fallback to mapping view if this is a dict-like object
        return list(self.values())

    # Otherwise, gather requested values
    out = []
    for k in keys:
        # Handle numeric indices (int or numeric strings)
        if isinstance(k, int) or (isinstance(k, str) and k.isdigit()):
            idx = int(k)
            if hasattr(self, "_items"):
                try:
                    out.append(self._items[idx])
                except IndexError as exc:
                    raise IndexError(f"Index {k} out of range.") from exc
            else:
                # Fallback: treat numeric keys as actual dict keys
                if k in self:
                    out.append(self[k])
                else:
                    raise KeyError(f"Key {k} not found.")
        else:
            # Treat as a dict key
            if k in self:
                out.append(self[k])
            else:
                raise KeyError(f"Key {k} not found.")
    return out

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key.
    Keys provided that are not in the record will be inserted with a
    value of :const:`None`; indexes provided that are out of bounds
    will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Assume the record stores field names in ``self._fields`` and
    # corresponding values in ``self._data``.
    if not keys:
        return dict(zip(self._fields, self._data))

    result = {}
    for k in keys:
        if isinstance(k, int):
            # index based access
            if k < 0 or k >= len(self._data):
                raise IndexError(f"Index {k} out of bounds")
            name = self._fields[k]
            result[name] = self._data[k]
        else:
            # key based access
            name = k
            if name in self._fields:
                idx = self._fields.index(name)
                result[name] = self._data[idx]
            else:
                result[name] = None
    return result

def deprecated(message):
    """Decorator for deprecating functions and methods.
    ::
        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    def _make_key(args, kw, typed):
        key = args
        if kw:
            key += tuple(sorted(kw.items()))
        if typed:
            # include the type of each argument in the key
            key += tuple(type(v) for v in args)
            if kw:
                key += tuple(type(v) for _, v in sorted(kw.items()))
        return tuple(key)

    def decorator(func):
        cache = {}
        order = []  # list of keys, least recently used first
        hit_count = 0
        miss_count = 0

        def wrapper(*args, **kwargs):
            nonlocal hit_count, miss_count
            key = _make_key(args, kwargs, typed)
            now = timer()

            # Check for cached value
            if key in cache:
                value, expire_time = cache[key]
                if expire_time >= now:
                    # Cache hit: move key to end of order list
                    try:
                        order.remove(key)
                    except ValueError:
                        pass
                    order.append(key)
                    hit_count += 1
                    return value
                else:
                    # Cache entry expired
                    del cache[key]
                    try:
                        order.remove(key)
                    except ValueError:
                        pass

            # Cache miss: compute value
            value = func(*args, **kwargs)
            expire_time = now + ttl
            cache[key] = (value, expire_time)
            order.append(key)
            miss_count += 1

            # Evict if over maxsize
            if len(order) > maxsize:
                oldest_key = order.pop(0)
                del cache[oldest_key]

            return value

        def cache_info():
            return {
                "hits": hit_count,
                "misses": miss_count,
                "maxsize": maxsize,
                "currsize": len(order),
            }

        def cache_clear():
            nonlocal hit_count, miss_count
            cache.clear()
            order.clear()
            hit_count = miss_count = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper

    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm."""
    def decorator(func):
        cache = {}
        order = []

        def _make_key(*args, **kwargs):
            key = args
            if kwargs:
                key += tuple(sorted(kwargs.items()))
            if typed:
                key += tuple(type(a) for a in args)
                key += tuple(type(v) for _, v in sorted(kwargs.items()))
            return key

        @wraps(func)
        def wrapper(*args, **kwargs):
            k = _make_key(*args, **kwargs)
            if k in cache:
                # Move key to end to mark as most recently used
                order.remove(k)
                order.append(k)
                return cache[k]
            result = func(*args, **kwargs)
            cache[k] = result
            order.append(k)
            if len(order) > maxsize:
                # Evict the most recently used key
                evict_k = order.pop()
                del cache[evict_k]
            return result

        def forget(*args, **kwargs):
            k = _make_key(*args, **kwargs)
            if k in cache:
                del cache[k]
                order.remove(k)

        def clear():
            cache.clear()
            order.clear()

        wrapper.forget = forget
        wrapper.clear = clear
        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm."""
    def decorator(func):
        cache = OrderedDict()

        @wraps(func)
        def wrapper(*args, **kwargs):
            if kwargs:
                kw = tuple(sorted(kwargs.items()))
            else:
                kw = ()
            if typed:
                key = (tuple((x, type(x)) for x in args), kw)
            else:
                key = (args, kw)
            if key in cache:
                cache.move_to_end(key)
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return result

        return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        freq = {}
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Build a hashable key from arguments
            key = args
            if kwargs:
                key += tuple(sorted(kwargs.items()))
            if typed:
                # Include types in the key when typed flag is True
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))
            if key in cache:
                freq[key] += 1
                return cache[key]
            # Compute the value and store it
            value = func(*args, **kwargs)
            if len(cache) >= maxsize:
                # Evict least frequently used key (ties broken arbitrarily)
                minfreq = min(freq.values())
                evict_key = None
                for k in freq:
                    if freq[k] == minfreq:
                        evict_key = k
                        break
                if evict_key is not None:
                    cache.pop(evict_key, None)
                    freq.pop(evict_key, None)
            cache[key] = value
            freq[key] = 1
            return value
        return wrapper
    return decorator

def popitem(self):
        """Remove and return the `(key, value)` pair first inserted."""
        # Attempt to find the first inserted key-value pair
        for key, value in self.items():
            # Remove the key from the dictionary
            self.pop(key)
            return (key, value)
        # If we reach here, the dictionary was empty
        raise KeyError('dict is empty')

