def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    cls_name = self.__class__.__name__
    for suffix in ('Py', 'Fallback'):
        if cls_name.endswith(suffix):
            cls_name = cls_name[:-len(suffix)]
            break
    module = __import__(self.__class__.__module__, fromlist=[cls_name])
    return getattr(module, cls_name)

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    kept = []
    for i, cls in enumerate(classes):
        # If the item is not a class there is nothing to reduce
        if not isinstance(cls, type):
            kept.append(cls)
            continue
        # Skip if an already kept class is a subclass of this one
        if any(isinstance(k, type) and issubclass(k, cls) for k in kept):
            continue
        # Skip if a later class in the list is a subclass of this one
        if any(isinstance(l, type) and issubclass(l, cls) for l in classes[i + 1:]):
            continue
        kept.append(cls)
    return kept

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if all:
        # Return all public attributes, including methods, from the instance
        return [name for name in dir(self) if not name.startswith("_")]
    # Return only public data attributes defined directly on the class
    return [
        name
        for name, value in self.__class__.__dict__.items()
        if not name.startswith("_") and not callable(value)
    ]

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if Broken in getattr(sequence, '__bases__', ()):
        return [sequence]

    cls = sequence.__class__
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        for v in sequence:
            _normalizeargs(v, output)

    return output

