def to_csv(self, separator=",", header=None):
    """Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    # Determine the iterable of points: prefer attribute `points`,
    # otherwise assume the instance itself is iterable.
    points_iter = getattr(self, "points", None)
    if points_iter is None:
        points_iter = self

    lines = []
    if header is not None:
        lines.append(header)

    for point in points_iter:
        # Expecting point to be a tuple (coordinate, value)
        try:
            coordinate, value = point
        except Exception:
            # If point cannot be unpacked, skip it
            continue

        # Convert coordinate parts to string
        if isinstance(coordinate, (str, bytes)):
            coord_parts = [str(coordinate)]
        elif hasattr(coordinate, "__iter__"):
            coord_parts = [str(p) for p in coordinate]
        else:
            coord_parts = [str(coordinate)]

        # Convert value parts to string
        if isinstance(value, (str, bytes)):
            val_parts = [str(value)]
        elif hasattr(value, "__iter__"):
            val_parts = [str(v) for v in value]
        else:
            val_parts = [str(value)]

        row = separator.join(coord_parts + val_parts)
        lines.append(row)

    return "\n".join(lines)

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Strings and bytes are not sequences we care about
    if isinstance(seq, (str, bytes)):
        return False
    # Exclude explicit Source sequences
    try:
        if isinstance(seq, Source):
            return False
    except NameError:
        # Source not defined; ignore
        pass
    # Check if seq itself is a FillRequest element
    try:
        if isinstance(seq, FillRequest):
            return True
    except NameError:
        # FillRequest not defined; fall through
        pass
    # If seq is iterable, check elements
    try:
        for elem in seq:
            try:
                if isinstance(elem, FillRequest):
                    return True
            except NameError:
                # If FillRequest unknown, skip element
                pass
    except TypeError:
        # seq not iterable
        pass
    return False

