def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    default_schemas = {}
    # Iterate over resources defined in the manifest
    for resource_name, resource_obj in getattr(app.spec, "manifest", {}).items():
        # Check for a custom observer schema
        custom_schema = None
        if hasattr(resource_obj, "observer_schema"):
            custom_schema = getattr(resource_obj, "observer_schema")
        elif isinstance(resource_obj, dict):
            custom_schema = resource_obj.get("observer_schema")
        if custom_schema is not None:
            default_schemas[resource_name] = custom_schema
            continue
        # Generate a simple default schema when none is provided
        default_schemas[resource_name] = {
            "metadata": {"path": "/metadata"},
            "spec": {"path": "/spec"},
            "status": {"path": "/status"},
        }
    return default_schemas

