def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    status = getattr(self, 'status', None)
    if status is None:
        return prefix
    # Prefer enum name if available; otherwise fall back to a mapping or string conversion
    if hasattr(status, 'name'):
        text = status.name
    elif hasattr(self, '_STATUS2STR'):
        text = self._STATUS2STR.get(status, str(status))
    else:
