def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Retrieve the validation log stored on the instance (if any).
    logs = getattr(self, "_validation_log", [])
    if not logs:
        # If there are no logs, return just the prefix or an empty string.
        return prefix
    # Prepend the prefix to each log entry and join them with newlines.
    prefixed_logs = [f"{prefix}{log}" for log in logs]
    return "\n".join(prefixed_logs)

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # 1. Extract specification version from inventory type if requested
    if extract_spec_version:
        inv_type = inventory.get('type')
        if inv_type is not None:
            try:
                # Assume a mapping from type names to spec versions exists
                self.spec_version = self._spec_version_by_type(inv_type)
            except KeyError:
                # Unknown type; retain the pre-set self.spec_version
                pass

    # 2. Validate that mandatory top‑level keys exist
    for key in getattr(self, 'required_keys', ()):
        if key not in inventory:
            raise ArgumentError(key, f"Missing required key '{key}' in inventory")

    # 3. Validate each field against its specification
    for field_name, field_spec in getattr(self, 'spec', {}).items():
        if field_name not in inventory:
            # Skip optional fields
            if field_spec.get('required', False):
                raise ArgumentError(field_name, f"Field '{field_name}' is required but missing")
            continue
        value = inventory[field_name]
        self._validate_field(value, field_spec, field_name)

    # 4. Ensure there are no unknown fields
    for key in inventory:
        if key not in self.spec:
            raise ArgumentError(key, f"Unknown field '{key}' found in inventory")

    # 5. Return the validated inventory (or simply True)
    return inventory

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    needed = set()
    for mf in manifest_files:
        # Expected that each manifest entry has a digest attribute
        digest = getattr(mf, 'digest', None) or getattr(mf, 'sha256', None)
        if digest:
            needed.add(digest)
    missing = needed - digests_used
    if missing:
        raise ValueError(f"Missing required digests: {', '.join(missing)}")
    # Optional: also warn about digests that were used but not referenced
    unused = digests_used - needed
    if unused:
        raise ValueError(f"Digests used but not referenced by manifest: {', '.join(unused)}")
    return True

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Make sure the prior object is of the same type
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an {type(self).__name__} instance, got {type(prior).__name__}")

    # Verify that the prior is actually older (by version or timestamp)
    if hasattr(self, "version") and hasattr(prior, "version"):
        if prior.version >= self.version:
            raise ValueError(f"Prior inventory version {prior.version} is not older than current version {self.version}")
    elif hasattr(self, "timestamp") and hasattr(prior, "timestamp"):
        if prior.timestamp >= self.timestamp:
            raise ValueError(f"Prior inventory timestamp {prior.timestamp} is not older than current timestamp {self.timestamp}")

    def _compare_attribute(name):
        """Compare two attributes of the current and prior inventories."""
        try:
            curr_val = getattr(self, name)
            prior_val = getattr(prior, name)
        except AttributeError:
            # If either attribute is missing, skip this check
            return

        # If the attribute has a shape/rows/cols, compare those
        if hasattr(curr_val, "shape"):
            if curr_val.shape != prior_val.shape:
                raise ValueError(f"Attribute '{name}' shape mismatch: current {curr_val.shape}, prior {prior_val.shape}")
        elif hasattr(curr_val, "rows") and hasattr(curr_val, "cols"):
            if (curr_val.rows, curr_val.cols) != (prior_val.rows, prior_val.cols):
                raise ValueError(f"Attribute '{name}' size mismatch: current ({curr_val.rows},{curr_val.cols}), prior ({prior_val.rows},{prior_val.cols})")
        # For iterable collections, compare the sets of items
        elif isinstance(curr_val, (list, tuple, set, dict)):
            if set(curr_val) != set(prior_val):
                raise ValueError(f"Attribute '{name}' content mismatch between current and prior inventories.")
        else:
            if curr_val != prior_val:
                raise ValueError(f"Attribute '{name}' values differ between current and prior inventories.")

    # Attributes that should match exactly
    for attr in ("species", "propensities", "stoichiometry_matrix"):
        _compare_attribute(attr)

    # Ensure that the prior does not reference any new species or propensities
    def _check_subset(attr):
        try:
            curr_set = set(getattr(self, attr))
            prior_set = set(getattr(prior, attr))
        except AttributeError:
            return
        if not prior_set.issubset(curr_set):
            missing = prior_set - curr_set
            raise ValueError(f"Prior inventory's '{attr}' contains {missing} not present in current inventory.")

    for attr in ("species", "propensities"):
        _check_subset(attr)

    # All checks passed
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for logical_path, entry in inventory.items():
        files = set()

        if isinstance(entry, dict):
            # Direct file reference
            if "file" in entry:
                files.add(entry["file"])

            # Versioned file list: dict of version -> file(s)
            if "files" in entry and isinstance(entry["files"], dict):
                for ver, file_obj in entry["files"].items():
                    # Include files for the target version or any later version
                    try:
                        if ver == version or ver > version:
                            if isinstance(file_obj, (list, set, tuple)):
                                files.update(file_obj)
                            else:
                                files.add(file_obj)
                    except Exception:
                        # If comparison fails, fall back to include all
                        if isinstance(file_obj, (list, set, tuple)):
                            files.update(file_obj)
                        else:
                            files.add(file_obj)

            # If entry contains an iterable of files directly
            if isinstance(entry, (list, set, tuple)):
                files.update(entry)

        elif isinstance(entry, (list, set, tuple)):
            files.update(entry)

        else:
            # Non-iterable entry is treated as a singular file path
            files.add(entry)

        logical_path_map[logical_path] = files

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dict")

    # The block must contain a list of files
    if 'files' not in fixity:
        raise ValueError("Missing 'files' key in fixity block")
    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("'files' must be a list")

    # Validate each entry
    seen_paths = set()
    for entry in files:
        if not isinstance(entry, dict):
            raise ValueError("Each entry in 'files' must be a dict")
        if 'path' not in entry:
            raise ValueError("Each file entry must contain a 'path' key")
        if 'checksum' not in entry:
            raise ValueError("Each file entry must contain a 'checksum' key")

        path = entry['path']

        # Ensure only files from the manifest are referenced
        if path not in manifest_files:
            raise ValueError(f"Fixity references file not in manifest: {path}")

        # Avoid duplicate references
        if path in seen_paths:
            raise ValueError(f"Duplicate path in fixity block: {path}")
        seen_paths.add(path)

    return True

def files_list(path):
    """Return the files in `path`"""
    if os.path.isfile(path):
        return [os.path.abspath(path)]
    elif os.path.isdir(path):
        files = []
        for root, dirs, filenames in os.walk(path):
            for f in filenames:
                files.append(os.path.join(root, f))
        return files
    else:
        raise FileNotFoundError(path)

def add_rendition(self, lang, file_path):
    """
    Add a rendition for a given language.

    Example mapping after addition:
        {
            "original": "artigo02.pdf",
            "en": "artigo02-en.pdf",
        }
    """
    # Ensure the renditions dictionary exists on this instance.
    if not hasattr(self, "renditions"):
        self.renditions = {}

    # Store the path for the requested language.
    self.renditions[lang] = file_path

    # If the "original" key is not already present, assume the first
    # file added for any language is the original.
    if "original" not in self.renditions:
        # Keep only the filename without directory components.
        self.renditions["original"] = os.path.basename(file_path)

    return self.renditions

def add_asset(self, basename, file_path):
    """
    "{
        "artigo02-gf03.tiff": "/path/artigo02-gf03.tiff",
        "artigo02-gf03.jpg": "/path/artigo02-gf03.jpg",
        "artigo02-gf03.png": "/path/artigo02-gf03.png",
    }
    """
    extensions = ['.tiff', '.jpg', '.png']
    mapping = {}
    for ext in extensions:
