def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath in pubdate_xpaths:
        try:
            if hasattr(node, "xpath"):
                matches = node.xpath(xpath)
            else:
                matches = node.select(xpath)
        except Exception:
            continue
        if matches:
            return matches[0]
    return None

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner_func

def get_versions(default="unknown"):
    """Get version information or return default if unable to do so."""
    try:
        # Python 3.8+
        from importlib.metadata import version
    except ImportError:
        try:
            # Backport for older Python versions
            from importlib_metadata import version
        except ImportError:
            return default

    # Prefer the package name if this module is part of a package,
    # otherwise fall back to the module's name.
    pkg_name = __package__ or __name__
    try:
        return version(pkg_name)
    except Exception:
        return default

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not pieces:
        return ''
    filtered = [str(p) for p in pieces if p is not None and str(p) != '']
    if not filtered:
        return ''

    # If style is a callable, use it directly
    if callable(style):
        return style(filtered)

    if not isinstance(style, str):
        raise TypeError('style must be a string or a callable')

    style_key = style.strip().lower()
    if style_key in ('full', 'standard'):
        delimiter = '.'
        subs = filtered
    elif style_key == 'short':
        delimiter = '.'
        subs = filtered[:2]
    elif style_key in ('compact', 'shortest'):
        delimiter = ''
        subs = filtered
    else:
        # fall back to default full style
        delimiter = '.'
        subs = filtered

    return delimiter.join(subs)

def plus_or_dot(pieces):
    """Return a '+' if we don't already have one, else return a '.'."""
    if any('+' in str(p) for p in pieces):
        return '.'
    return '+'

def register_vcs_handler(vcs, method):  # tyoe: (str, str) -> typing.Callable  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(f):
        """Store f in HANDLERS[vcs][method]."""
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    # Retrieve all objects in the hierarchy.  Subclasses may override the
    # `get_all_objects` method to provide the appropriate iterator.
    try:
        objects = self.get_all_objects()
    except AttributeError:
        # Fallback: look for an attribute named 'objects' or iterate over the
        # existing container if it implements __iter__.
        objects = getattr(self, 'objects', [])
    for obj in objects:
        num_objects += 1
        is_valid = True
        if validate_objects:
            try:
                obj.validate()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    import warnings
                    warnings.warn(
                        f"Validation failed for object {getattr(obj, 'id', obj)}: {exc}"
                    )
        if check_digests:
            try:
                obj.check_digest()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    import warnings
                    warnings.warn(
                        f"Digest check failed for object {getattr(obj, 'id', obj)}: {exc}"
                    )
        if is_valid:
            good_objects += 1
    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version or not version.isdigit():
        return ""
    new_num = int(version) + 1
    new_str = str(new_num)
    if len(new_str) < len(version):
        # Preserve original zero padding
        return new_str.rjust(len(version), "0")
    return new_str

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Load the root inventory once
    root_inventory_path = os.path.join(self.root, "inventory.json")
    try:
        with open(root_inventory_path, "r") as fh:
            root_inventory = json.load(fh)
    except Exception as exc:
        raise ValueError(f"Failed to read root inventory '{root_inventory_path}': {exc}")

    # Keep mismatches per version
    self._mismatched_digests = {}

    for vdir in version_dirs:
        inv_path = os.path.join(self.root, vdir, "inventory.json")
        if not os.path.exists(inv_path):
            raise ValueError(f"Missing inventory for version directory '{vdir}'")

        try:
            with open(inv_path, "r") as fh:
                inv = json.load(fh)
        except Exception as exc:
            raise ValueError(f"Failed to read inventory '{inv_path}': {exc}")

        # Compare digests to root inventory
        mismatches = {}
        for name, digest in inv.items():
            root_digest = root_inventory.get(name)
            if root_digest is None:
                mismatches[name] = {"in_root": None, "in_version": digest}
            elif root_digest != digest:
                mismatches[name] = {"in_root": root_digest, "in_version": digest}

        for name in root_inventory:
            if name not in inv:
                mismatches[name] = {"in_root": root_inventory[name], "in_version": None}

        if mismatches:
            self._mismatched_digests[vdir] = mismatches

    return self

