def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    return {
        ('^' + re.escape(k).replace(r'\*', '.*') + '$' if '*' in k else k): v
        for k, v in item.items()
    }

def unquote(name):
    """Remove quote from the given name."""
    if len(name) > 1:
        if name[0] == '"' and name[-1] == '"':
            return name[1:-1].replace(r'\\"', '"').replace(r'\\', '\\')
        if name[0] == "'" and name[-1] == "'":
            return name[1:-1].replace(r"\\'", "'").replace(r'\\', '\\')
        if name[0] == '<' and name[-1] == '>':
            return name[1:-1]
    return name

def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list,
    sort the list for only ignored files, return those files as a single
    string with each filename separated by a comma."""
    try:
        output = subprocess.check_output(
            ["git", "ls-files", "--others", "--ignored", "--exclude-standard"],
            stderr=subprocess.STDOUT
        )
        files = output.decode("utf-8").strip().splitlines()
    except subprocess.CalledProcessError:
        files = []

    files = [f for f in files if f]
    files.sort()
    return ",".join(files)

def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None:
        return None
    if isinstance(frequency, str):
        freq = frequency.strip().lower()
        if freq == "always":
            return None
    else:
        raise ValueError("Frequency must be a string, None, or 'always'")

    import re
    match = re.match(r'^(?P<num>\d+)\s*(?P<unit>\w+)$', freq)
    if not match:
        raise ValueError(f"Cannot parse frequency: {frequency}")

    num = int(match.group('num'))
    unit = match.group('unit')

    unit_map = {
        'second': 'seconds',
        'seconds': 'seconds',
        'minute': 'minutes',
        'minutes': 'minutes',
        'hour': 'hours',
        'hours': 'hours',
        'day': 'days',
        'days': 'days',
        'week': 'weeks',
        'weeks': 'weeks',
        'month': 'days',
        'months': 'days',
    }

    if unit not in unit_map:
        raise ValueError(f"Unrecognized time unit: {unit}")

    if unit in ('month', 'months'):
        # approximate a month as 30 days
        return datetime.timedelta(days=num * 30)

    kwargs = {unit_map[unit]: num}
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        for res in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = res
            addr = sockaddr[0]
            if family == socket.AF_INET and addr == '127.0.0.1':
                return True
            if family == socket.AF_INET6 and addr in ('::1', '0:0:0:0:0:0:0:1'):
                return True
    except socket.gaierror:
        return False
    return False

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a
    name and an optional default value.
    If the variable is not defined in environment and no default value
    is provided, an Error is raised.
    """
    # Extract name and default from the matcher.  The matcher may be a
    # dictionary, a SimpleNamespace, or an object with `name` and
    # `default` attributes.  Use a fallback strategy to support
    # whichever is passed.
    if hasattr(matcher, 'name'):
        name = getattr(matcher, 'name')
    else:
        name = matcher.get('name')
    if hasattr(matcher, 'default'):
        default = getattr(matcher, 'default')
    else:
        default = matcher.get('default')
    # Retrieve the value from the environment.
    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        raise KeyError(f"Environment variable '{name}' not found and no default supplied")
    return str(value)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    cmd_parts = []

    # Accept a single command as a string or a list of strings or a list of lists
    if isinstance(commands, str):
        cmd_parts.append(commands)
    elif isinstance(commands, (list, tuple)):
        for cmd in commands:
            if isinstance(cmd, (list, tuple)):
                cmd_parts.extend(cmd)
            else:
                cmd_parts.append(cmd)
    else:
        raise TypeError("commands must be a str, list, or tuple")

    # Append args if they are provided
    if args:
        if isinstance(args, str):
            cmd_parts.append(args)
        elif isinstance(args, (list, tuple)):
            cmd_parts.extend(args)
        else:
            raise TypeError("args must be a str, list, or tuple")

    # Set up stderr handling
    stderr_option = subprocess.DEVNULL if hide_stderr else subprocess.PIPE

    # Run the command
    result = subprocess.run(
        cmd_parts,
        cwd=cwd,
        env=env,
        stdout=subprocess.PIPE,
        stderr=stderr_option,
        text=True
    )

    # Optional verbose output
    if verbose:
        print("Command:", " ".join(cmd_parts))
        print("Output:", result.stdout.strip())
        if not hide_stderr and result.stderr:
            print("Error:", result.stderr.strip())

    return result

def is_ipv4(target):
    """ Test if IPv4 address or not """
    try:
        return isinstance(ipaddress.ip_address(target), ipaddress.IPv4Address)
