def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    # Use the provided Dumper or fallback to SafeDumper
    if dumper is None:
        dumper = yaml.SafeDumper
    # Dump the object, ensuring unicode output on Python 3 and proper encoding on Python 2
    result = yaml.dump(obj,
                       Dumper=dumper,
                       default_flow_style=False,
                       allow_unicode=True)
    # On Python 2, yaml.dump returns a byte string; convert it to unicode.
    if isinstance(result, bytes):
        try:
            return result.decode('utf-8')
        except UnicodeDecodeError:
            # If decoding fails, return the original byte string
            return result
    return result

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    x = np.array(x)
    return np.exp(-0.5 * ((x - 0.2) / 0.1) ** 2) / (0.1 * np.sqrt(2 * np.pi))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
        - dict of configuration filename to corresponding parsed configuration,
        - sequence of logging.LogRecord instances containing any parse errors.
    """
    configs = {}
    error_records = []

    def _resolve_env_in_dict(d):
        """Recursively replace strings containing $VAR or ${VAR} with environment values."""
        if isinstance(d, dict):
            return {k: _resolve_env_in_dict(v) for k, v in d.items()}
        elif isinstance(d, list):
            return [_resolve_env_in_dict(v) for v in d]
        elif isinstance(d, str):
            import os
            try:
                # Simple shell-style expansion
                return os.path.expandvars(d)
            except Exception:
                return d
        else:
            return d

    for fname in config_filenames:
        try:
            with open(fname, 'r') as fd:
                raw = fd.read()
            # Attempt parsing based on file extension
            if fname.lower().endswith('.toml'):
                cfg = toml.loads(raw)
            elif fname.lower().endswith(('.yaml', '.yml')):
                cfg = yaml.safe_load(raw)
            else:
                # Fallback to YAML as a generic parser
                cfg = yaml.safe_load(raw)
            if overrides:
                cfg.update(overrides)
            if resolve_env:
                cfg = _resolve_env_in_dict(cfg)
            configs[fname] = cfg
        except Exception as exc:
            # Create a LogRecord for each failure
            import sys
            rec = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f"Failed to load '{fname}': {exc}",
                args=(),
                exc_info=sys.exc_info()
            )
            error_records.append(rec)

    return configs, error_records

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Fast‑path for built‑in sequence types (except str/bytes, which we treat specially)
    if isinstance(seq, (list, tuple, set, frozenset)):
        return seq, type(seq)

    # Strings and bytes are iterable but are usually treated as raw data
    if isinstance(seq, (str, bytes)):
        return seq, type(seq)

    # Arbitrary iterable (not string/bytes) – return as is
    if hasattr(seq, "__iter__"):
        return seq, type(seq)

    # File‑like object: read its contents
    if hasattr(seq, "read"):
        # If a file‑path string was accidentally treated as file‑like (i.e. a string without 'read')
        # then the following will raise and be caught below.
        data = seq.read()
        return data, type(seq)

    # Fallback: treat the object as a single element sequence
    return [seq], list

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Identify bin edges attribute.
    if hasattr(hist, "edges"):
        edges = hist.edges
    elif hasattr(hist, "bin_edges"):
        edges = hist.bin_edges
    else:
        raise AttributeError("Histogram must provide 'edges' or 'bin_edges'.")
    if len(edges) < 2:
        raise ValueError("Histogram edges must contain at least two values.")
    # Determine the coordinate for each bin.
    if get_coordinate == "left":
        coords = edges[:-1]
    elif get_coordinate == "right":
        coords = edges[1:]
    elif get_coordinate == "middle":
        coords = [(l + r) / 2 for l, r in zip(edges[:-1], edges[1:])]
    else:
        raise ValueError("get_coordinate must be 'left', 'right' or 'middle'.")
    # Obtain bin contents.
    if hasattr(hist, "bins"):
        bins = hist.bins
    elif hasattr(hist, "counts"):
        bins = hist.counts
    else:
        raise AttributeError("Histogram must provide 'bins' or 'counts'.")
    if len(coords) != len(bins):
        raise ValueError("Number of edges and bins differ.")
    # Construct graph points.
    points = []
    for coord, bin_val in zip(coords, bins):
        if make_value is None:
            values = (bin_val,)
        else:
            values = make_value(bin_val)
            if not isinstance(values, (tuple, list)):
                values = (values,)
        if len(values) + 1 != len(field_names):
            raise ValueError(
                "make_value returned %d values, but field_names has %d entries."
                % (len(values), len(field_names))
            )
        point = {name: val for name, val in zip(field_names, (coord,) + values)}
        points.append(point)
    # Build the final graph data structure.
    graph = {"points": points}
    # Include scale information if requested.
    if scale is True and hasattr(hist, "scale"):
        graph["scale"] = hist.scale
    elif scale is not None:
        graph["scale"] = scale
    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is ``True``,
      in which case this step is skipped). This means that the candidate's class
      declares that it ``implements`` the interface, or the candidate itself declares
      that it ``provides`` the interface.

    - Making sure the candidate defines all the necessary methods.

    - Making sure the methods have the correct signature (to the
      extent possible).

    - Making sure the candidate defines all the necessary attributes.

    :return bool: Returns a true value if everything that could be
       checked passed.

    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    errors = []

    # Step 1: Verify that the candidate claims to provide the interface
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(
                    f"Candidate does not claim to provide interface {iface.__name__}"
                )
        except Exception as exc:  # pragma: no cover
            errors.append(
                f"Error checking provided interface: {exc!s}"
            )

    # Step 2: Gather interface members (methods and attributes)
    # We filter out private names and special attributes
    try:
        interface_attrs = [
            nm
            for nm in iface.__dict__
            if not nm.startswith("_")
            and not callable(iface.__dict__[nm])
        ]
        interface_methods = [
            nm
            for nm, val in iface.__dict__.items()
            if not nm.startswith("_") and callable(val)
        ]
    except Exception:  # pragma: no cover
        # Fallback: use dir() if __dict__ access fails
        interface_attrs = [
            nm
            for nm in dir(iface)
            if not nm.startswith("_")
            and not callable(getattr(iface, nm, None))
        ]
        interface_methods = [
            nm
            for nm in dir(iface)
            if not nm.startswith("_") and callable(getattr(iface, nm, None))
        ]

    # Determine candidate type: class or instance
    candidate_type = candidate if isinstance(candidate, type) else type(candidate)

    import inspect  # Local import as no top-level imports allowed

    # Step 3: Verify methods
    for name in interface_methods:
        if not hasattr(candidate_type, name):
            errors.append(f"Missing method '{name}'")
        else:
            iface_method = getattr(iface, name)
            cand_method = getattr(candidate_type, name)
            try:
                sig_iface = inspect.signature(iface_method)
                sig_cand = inspect.signature(cand_method)
            except Exception:  # pragma: no cover
                # Unable to introspect signatures – skip detailed comparison
                continue
            if sig_iface != sig_cand:
                errors.append(
                    f"Signature mismatch for method '{name}': "
                    f"expected {sig_iface}, got {sig_cand}"
                )

    # Step 4: Verify attributes
    for name in interface_attrs:
        if not hasattr(candidate_type, name):
            errors.append(f"Missing attribute '{name}'")

    # Final: Raise if any errors were collected
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])  # pragma: no cover
        raise Invalid("; ".join(errors))  # pragma: no cover

    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    # Resolve the class of the candidate
    cand_cls = candidate if isinstance(candidate, type) else candidate.__class__
    # If the candidate is a subclass of the interface, it trivially satisfies it
    if issubclass(cand_cls, iface):
        return True
    # Gather required abstract methods from the interface, if any
    required = []
    for attr, obj in vars(iface).items():
        if getattr(obj, "__isabstractmethod__", False):
            required.append(attr)
    # Check that the candidate implements each required method
    missing = [name for name in required if not hasattr(cand_cls, name)]
    if missing and not tentative:
        raise TypeError(
            f"{cand_cls.__name__} does not implement required methods: "
            f"{', '.join(missing)}"
        )
    return True

def determineMetaclass(bases, explicit_mc=None):
        """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

        # If an explicit metaclass is given, it takes precedence.
        if explicit_mc is not None:
            meta_candidate = explicit_mc
        else:
            # Collect metaclasses of the given bases.
            metaclasses = [type(b) for b in bases if isinstance(b, type)]
            if not metaclasses:
                return object

            # Start with the first metaclass and attempt to
            # find a common super‑metaclass that satisfies all bases.
            meta_candidate = metaclasses[0]
            for other_meta in metaclasses[1:]:
                if issubclass(other_meta, meta_candidate):
                    meta_candidate = other_meta
                elif not issubclass(meta_candidate, other_meta):
                    # No common metaclass – fall back to object.
                    meta_candidate = object
                    break

        # Ensure the returned value is a real metaclass object.
        if not isinstance(meta_candidate, type):
            meta_candidate = type(meta_candidate)
        return meta_candidate

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self._store:
        raise KeyError('dict is empty')
    # Find key with lowest access count
    min_key = min(self._store, key=lambda k: self._freq.get(k, 0))
    value = self._store.pop(min_key)
    # Remove its frequency entry
    self._freq.pop(min_key, None)
    return (min_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    node = self._head[2]
    if node is self._tail:
        raise KeyError('list is empty')
    self._remove(node)
    return (node[0], node[1])

def _create_converter(self) -> _converting._Converter:
    """Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    return _converting._Converter()

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    # Ensure the datetime is timezone-aware and in UTC
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.timezone.utc)
    # Convert to UTC and format as ISO 8601 with trailing 'Z'
    return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    _URL_RE = re.compile(r'\b(?P<url>https?://[^\s<]+)')
    def _linkify(m):
        url = m.group('url')
        attrs = ' target="_blank" rel="noopener noreferrer"'
        return f'<a href="{url}"{attrs}>{url}</a>'
    return _URL_RE.sub(_linkify, text)

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    scheme, netloc, _, _, _ = urlsplit(url)
    if scheme not in ("http", "https", "ftp", "ftps"):
        return None

    req = Request(url, method="HEAD")
    req.add_header("Host", netloc)

    try:
        resp = urlopen(req)
        try:
            if hasattr(resp, "status") and resp.status != 200 and scheme not in ("ftp", "ftps"):
                return None
            content_type = resp.getheader("Content-Type")
            return content_type
        finally:
            resp.close()
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        return False
    if not tag:
        return False
    for c in tag:
        if not (c.isalnum() or c in ('-', '_')):
            return False
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        tag = child.tag
        # Strip namespace if present
        if '}' in tag:
            tag = tag.split('}', 1)[1]
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    base = url.rstrip('/')
    if document_path is None:
        document_path = '/nodeinfo/2.0'
    if not document_path.startswith('/'):
        document_path = '/' + document_path
    href = base + document_path
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    result: Dict[str, Any] = {}
    try:
        # Try JSON
        data = json.loads(document)
        # Subject
        if "subject" in data:
            result["subject"] = data["subject"]
        # Aliases
        if "aliases" in data:
            result["aliases"] = data["aliases"]
        # Properties
        if "properties" in data:
            result["properties"] = data["properties"]
        # Links
        for link in data.get("links", []):
            rel = link.get("rel")
            href = link.get("href")
            if not rel or not href:
                continue
            # Some rels are space separated
            for r in rel.split():
                if r == "hcard" or r in ("http://microformats.org/profile/hcard",
                                         "http://openid.net/specs/connect/1.0/authorization_endpoint"):
                    result["hcard_url"] = href
                # Store general mapping, allow list of values
                if r in result:
                    if isinstance(result[r], list):
                        result[r].append(href)
                    else:
                        result[r] = [result[r], href]
                else:
                    result[r] = href
        return result
    except Exception:
        # Not JSON, try XRD
        try:
            # Register a dummy namespace map to handle default namespace
            namespace = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
            root = ET.fromstring(document)
            # Subject
            sub = root.find("xrd:Subject", namespace)
            if sub is not None:
                result["subject"] = sub.text
            # Links
            for link in root.findall("xrd:Link", namespace):
                rel = link.get("rel")
                href = link.get("href")
                if not rel or not href:
                    continue
                for r in rel.split():
                    if r == "hcard" or r == "http://microformats.org/profile/hcard":
                        result["hcard_url"] = href
                    if r in result:
                        if isinstance(result[r], list):
                            result[r].append(href)
                        else:
                            result[r] = [result[r], href]
                    else:
                        result[r] = href
            return result
        except Exception:
            # Failed to parse
            return {}

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def list_of_file_names(settings_dirs, spec_option):
    """Return a sorted list of fully qualified file names from the provided directories.

    Parameters
    ----------
    settings_dirs : list or tuple of str
        Directories to search for files.
    spec_option : str or None
        Optional string to filter file names; only files whose names start with this
        string will be included. If None, all files are included.

    Returns
    -------
    list of str
        Sorted list of absolute paths to files that match the filter.
    """
    import os
    files = []
    for directory in settings_dirs:
        try:
            if not os.path.isdir(directory):
                continue
            for fname in os.listdir(directory):
                if spec_option and not fname.startswith(spec_option):
                    continue
                full_path = os.path.join(directory, fname)
                if os.path.isfile(full_path):
                    files.append(full_path)
        except OSError:
            # Skip directories that cannot be accessed
            continue
    return sorted(files)

