def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Iterate over a list copy of items so that we can modify the dict safely
    for parser_name, options in list(parser_dict.items()):
        include = options.pop('include', None)
        if not include:
            continue
        # If `include` is a mapping, insert the sub-parsers under the given keys
        if isinstance(include, dict):
            for local_key, inc_name in include.items():
                if inc_name not in parser_dict:
                    raise KeyError(f'Included parser {inc_name!r} not found')
                # Store a copy of the included spec so later changes do not affect the original
                options[local_key] = parser_dict[inc_name].copy()
        else:
            # Assume a sequence of parser names; merge into the current options
            for inc_name in include:
                if inc_name not in parser_dict:
                    raise KeyError(f'Included parser {inc_name!r} not found')
                options.update(parser_dict[inc_name])

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    for arg in getattr(self, "args", []):
        if not isinstance(arg, _BaseOpt):
            continue
        # Prefer an explicit value from the spec, if present
        if getattr(self, "spec", None) and arg.name in self.spec:
            defaults[arg.name] = self.spec[arg.name]
            continue
        # Fallback to the option's own default, if it has one
        if not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default
            continue
        # Handle nested dictionary options, merging defaults recursively
        if isinstance(arg, DictOption) and getattr(arg, "scheme", None):
            nested = arg.scheme.get_spec_defaults()
            if nested:
                defaults[arg.name] = nested
    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    # Define a mapping from deprecated option names to their current replacements.
    # Example:
    #     return {
    #         "old_option_name": "new_option_name",
    #         "unused_flag": "use_flag"
    #     }
    #
    # If no deprecations currently exist, return an empty dictionary.
    return {}

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments."""
    deprecated_map = getattr(self, 'deprecated_args', {})
    if not isinstance(cli_args, dict):
        cli_args = {}
    if not isinstance(answer_file_args, dict):
        answer_file_args = {}
    merged_args = {}
    merged_args.update(answer_file_args)
    merged_args.update(cli_args)
    for old_name, new_name in deprecated_map.items():
        if old_name in merged_args:
            print(f"Warning: argument '{old_name}' is deprecated; use '{new_name}' instead.")

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Retrieve the parser instance for the given command
    parser = getattr(self, "_parsers", {}).get(command_name)
    if parser is None:
        raise KeyError(f"Unknown command '{command_name}'.")
    # Prefer an explicit method if available; fall back to common attributes
    if hasattr(parser, "get_options"):
        return list(parser.get_options())
    if hasattr(parser, "options"):
        return list(parser.options)
    raise AttributeError("Parser does not expose options via 'options' attribute or 'get_options' method.")

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate inputs
    if not isinstance(command_name, (str, bytes)):
        raise TypeError("command_name must be a string")
    if not isinstance(argument_name, (str, bytes)):
        raise TypeError("argument_name must be a string")

    # Retrieve the command's specification dictionary
    cmd_spec = getattr(self, "_specs", {}).get(command_name)
    if cmd_spec is None:
        return None

    # Retrieve the specific argument's specification
    return cmd_spec.get(argument_name)

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Determine the list of required arguments, try common attribute names
    required = getattr(self, "_required_args", None)
    if required is None:
        required = getattr(self, "required", [])
    if not required:
        return
    # Validate each required argument
    for name in required:
        if isinstance(args, dict):
            # Key-based arguments should be present and not None
            if name not in args or args[name] is None:
                raise ValueError(f"Required argument '{name}' is missing.")
        else:
            # Attribute-based arguments (e.g., argparse.Namespace)
            if not hasattr(args, name) or getattr(args, name) is None:
                raise ValueError(f"Required argument '{name}' is missing.")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        # Skip if no conditional requirement defined
        if 'required_when' not in opt:
            continue
        cond = opt['required_when']
        matched = False
        # Try to evaluate the condition
        try:
            if callable(cond):
                # Try with both args and command_name first
                try:
                    matched = bool(cond(args, command_name))
                except TypeError:
                    # Fallback to single argument
                    matched = bool(cond(args))
            else:
                # Non-callable conditions: treat truthy values as True
                matched = bool(cond)
        except Exception:
            # If evaluation fails, treat as not matched
            matched = False
        if matched:
            # Prefer explicit name if provided, else dest
            name = opt.get('name') or opt.get('dest')
            if name:
                required.append(name)
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Retrieve argument specifications from parsed yaml
    args_def = self.parsed_yaml.get('args', {})
    for arg_name, arg_attrs in args_def.items():
        # Handle list format used for positional arguments
        if isinstance(arg_attrs, list):
            # The attribute dict should be the first (and only) element
            for item in arg_attrs:
                if isinstance(item, dict):
                    arg_attrs = item
                break
        # Only proceed if a maximum length is defined
        max_len = arg_attrs.get('len')
        if max_len is None:
            continue
        if arg_name not in args:
            continue
        value = args[arg_name]
        try:
            value_len = len(value)
        except Exception:
            # Not a sized object – skip length check
            continue
        if value_len > max_len:
            abort(
                f"Argument '{arg_name}' exceeds maximum length of {max_len} "
                f"(got length {value_len})"
            )

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if extra_vars is None:
        return vars_dict
    if isinstance(extra_vars, dict):
        extra_vars = [extra_vars]
    if not isinstance(extra_vars, (list, tuple)):
        raise TypeError("extra_vars must be a list, tuple, or dict")
    for var in extra_vars:
        if isinstance(var, dict):
            vars_dict.update(var)
        elif isinstance(var, str) and '=' in var:
            key, val = var.split('=', 1)
            vars_dict[key.strip()] = val.strip()
    return vars_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten_dict(d, parent_key='', sep='.', result=None):
        if result is None:
            result = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                _flatten_dict(v, new_key, sep=sep, result=result)
            else:
                result[new_key] = v
        return result

    spec_file = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.exists(spec_file):
        raise FileNotFoundError(f"Spec file not found: {spec_file}")

    with open(spec_file, 'r', encoding='utf-8') as f:
        spec = json.load(f)

    return _flatten_dict(spec)

def inject_config(self):
        """Set the environment variable for config path, if it is undefined."""
        env_var = 'CONFIG_PATH'
        if env_var not in os.environ:
            config_path = getattr(self, 'config_path', None)
            if config_path is not None:
                os.environ[env_var] = str(config_path)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    path = os.path.normpath(path)
    root = os.path.normpath(root)
    try:
        relative = os.path.relpath(path, root)
    except ValueError:
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    if relative == ".":
        return ""
    if relative.startswith(".." + os.sep) or relative == "..":
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    return relative
